import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const prefixes=['Moss','Ember','Brook','Cloud','Thorn','Dusk','Dawn','Pebble','Glimmer','Bramble'];
const suffixes=['ling','pup','finch','munk','horn','moth','cub','sprout','wisp','beetle'];
const emojis=['🦊','🐸','🦋','🐻','🐉','🦉','🐢','🐺','🐝','🦌','🐙','🐰','🦎','🐬','🦔','🐲','🐦','🦇','🐿️','🐌'];
const types=['Grove','Flame','Tide','Sky','Stone','Shade','Bloom','Spark','Frost','Wild'];
const typeColors=['#78a66b','#e47756','#559cb4','#86b7d4','#a78b66','#786b98','#d889a4','#ddbd54','#87b8c2','#9da47c'];
const species=Array.from({length:100},(_,i)=>{let name=prefixes[Math.floor(i/10)]+suffixes[i%10];return {id:i,name,type:types[(i*7+Math.floor(i/10))%10],emoji:emojis[(i*7+Math.floor(i/10))%emojis.length],color:typeColors[(i*7+Math.floor(i/10))%10],base:25+(i*13)%17,ability:['Verdant Pulse','Cinder Dash','Tidal Mend','Gale Step','Stone Skin','Night Veil','Petal Guard','Static Snap','Frostbite','Wildheart'][(i*7+Math.floor(i/10))%10]}});
const evolve={0:{to:1,level:6},1:{to:2,level:14},10:{to:11,level:7},20:{to:21,level:8},21:{to:22,level:16},30:{to:31,level:9},40:{to:41,level:8},50:{to:51,level:10},60:{to:61,level:9},70:{to:71,level:8},80:{to:81,level:12},90:{to:91,level:10}};
const saveKey='wildbound-save-v1';let state=(()=>{try{return JSON.parse(localStorage.getItem(saveKey))}catch{return null}})()||{party:[],box:[],seen:[],coins:120,rank:1,xp:0,starter:false};
let toastTimer;function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2100)}
function persist(){localStorage.setItem(saveKey,JSON.stringify(state));renderUI()}
function makeMon(id,level=3){let s=species[id];return {id,level,xp:0,hp:s.base+level*5,maxHp:s.base+level*5,atk:5+Math.floor(level/2)+(id%3),ability:s.ability}}
function aliveParty(){return state.party.find(m=>m.hp>0)}
function monName(m){return species[m.id]?.name||'Unknown'}
function renderUI(){ $('#coins').textContent=state.coins;$('#caughtCount').textContent=state.seen.length;$('#partyCount').textContent=`${state.party.length} / 6`;
 const list=$('#teamList');list.innerHTML='';if(!state.party.length)list.innerHTML='<div class="team-empty">Choose a companion to start your journey.</div>';state.party.forEach((m,i)=>{const s=species[m.id],r=document.createElement('div');r.className='team-row'+(aliveParty()===m?' active':'');r.innerHTML=`<div class="mon-mini" style="--monbg:${s.color}25">${s.emoji}</div><div class="team-info"><div class="team-n">${s.name}</div><div class="team-l">Lv. ${m.level} · ${s.type}</div><div class="hp-mini"><i style="width:${Math.max(0,100*m.hp/m.maxHp)}%"></i></div></div>`;r.title='Click to make active';r.onclick=()=>{state.party.splice(i,1);state.party.unshift(m);persist();toast(`${s.name} is leading the party.`)};list.append(r)});
 $('#rankText').textContent=String(state.rank).padStart(2,'0')+' · '+(state.rank<3?'ROOKIE':state.rank<7?'RANGER':'PATHFINDER');$('#xpFill').style.width=Math.min(100,state.xp%100)+'%';}
function addSeen(id){if(!state.seen.includes(id))state.seen.push(id)}
function openScreen(id){$('#'+id).classList.add('open');if(id==='storageScreen')renderStorage();if(id==='dexScreen')renderDex()}
function closeScreen(id){$('#'+id).classList.remove('open')}
$$('[data-close]').forEach(b=>b.onclick=()=>closeScreen(b.dataset.close));
function makeStarterChoices(){let ids=[0,10,20];$('#starterChoices').innerHTML=ids.map(id=>{let s=species[id];return `<button class="starter" data-starter="${id}"><div class="starter-emoji">${s.emoji}</div><h3>${s.name}</h3><p>${s.type} · ${s.ability}</p></button>`}).join('');$$('[data-starter]').forEach(b=>b.onclick=()=>{let m=makeMon(+b.dataset.starter,5);state.party.push(m);state.starter=true;addSeen(m.id);persist();closeScreen('starterScreen');toast(`${monName(m)} joined your journey!`);});}
makeStarterChoices();renderUI();if(state.starter)closeScreen('starterScreen');
$$('.nav-btn').forEach(b=>b.onclick=()=>{ $$('.nav-btn').forEach(x=>x.classList.remove('active'));b.classList.add('active');if(b.dataset.panel==='storage')openScreen('storageScreen');else if(b.dataset.panel==='dex')openScreen('dexScreen');});
let storeTab='party';function renderStorage(){ $('#storagePartyCount').textContent=state.party.length;$('#storageBoxCount').textContent=state.box.length;$('#storeHint').textContent=storeTab==='party'?'SELECT A CREATURE TO SEND TO SANCTUARY':'SELECT A CREATURE TO ADD TO PARTY';$$('[data-store-tab]').forEach(b=>b.classList.toggle('selected',b.dataset.storeTab===storeTab));let arr=storeTab==='party'?state.party:state.box,grid=$('#storageGrid');grid.innerHTML='';for(let i=0;i<Math.max(10,arr.length);i++){let m=arr[i],cell=document.createElement('button');cell.className='storage-cell'+(!m?' empty':'');if(m){let s=species[m.id];cell.innerHTML=`<div class="s-emoji">${s.emoji}</div><div class="s-name">${s.name}</div><div class="s-level">Lv. ${m.level} · ${m.hp}/${m.maxHp} HP</div>`;cell.onclick=()=>{if(storeTab==='party'){if(state.party.length<=1){toast('Keep at least one companion in your party.');return}state.party.splice(i,1);state.box.push(m);toast(`${s.name} moved to sanctuary.`)}else{if(state.party.length>=6){toast('Your party is full.');return}state.box.splice(i,1);state.party.push(m);toast(`${s.name} joined your party.`)}persist();renderStorage()}}else cell.textContent='empty';grid.append(cell)}}
$$('[data-store-tab]').forEach(b=>b.onclick=()=>{storeTab=b.dataset.storeTab;renderStorage()});$('#healAll').onclick=()=>{if(state.coins<20){toast('You need 20 ✦ to restore your party.');return}state.coins-=20;state.party.forEach(m=>m.hp=m.maxHp);persist();renderStorage();toast('Your party is feeling fresh again!')};
function renderDex(){let grid=$('#dexGrid');grid.innerHTML='';species.forEach(s=>{let known=state.seen.includes(s.id),el=document.createElement('div');el.className='dex-card'+(known?'':' locked');el.innerHTML=`<div>${known?s.emoji:'?'}</div><b>${known?s.name:'Undiscovered'}</b><small>#${String(s.id+1).padStart(3,'0')} · ${known?s.type:'???'}</small>`;grid.append(el)});$('#dexProgress').textContent=`${state.seen.length} of 100 species discovered · catch them all to complete your atlas.`}

