function startBattle(w){if(!state.party.length){toast('Choose your first companion!');openScreen('starterScreen');return}if(!aliveParty()){state.party[0].hp=state.party[0].maxHp;persist()}let s=species[w.userData.id];battle={wild:w,id:s.id,hp:s.base+Math.floor(Math.random()*9)+8,maxHp:s.base+Math.floor(Math.random()*9)+8}; // normalize its max after roll
battle.maxHp=battle.hp;turnBusy=false;$('#battleTitle').textContent=`A wild ${s.name} appeared!`;$('#wildSprite').textContent=s.emoji;$('#battleLog').textContent=`A wild ${s.name} blocks your path. What will you do?`;closeScreen('storageScreen');openScreen('battleScreen');renderBattle();}
function renderBattle(){if(!battle)return;let ally=aliveParty()||state.party[0],s=species[ally.id],wild=species[battle.id];$('#allySprite').textContent=s.emoji;$('#wildSprite').textContent=wild.emoji;$('#allyStatus').innerHTML=`${s.name} · Lv.${ally.level}<div class="battle-hp"><i style="width:${100*ally.hp/ally.maxHp}%"></i></div>`;$('#wildStatus').innerHTML=`${wild.name} · Lv.${Math.max(2,ally.level-1)}<div class="battle-hp"><i style="width:${100*battle.hp/battle.maxHp}%"></i></div>`;let acts=$('#battleActions');acts.innerHTML=`<button class="move-btn" data-action="tackle">🌿 Trail Swipe <small>QUICK · reliable hit</small></button><button class="move-btn" data-action="ability">✦ ${s.ability}<small>SPECIAL · signature skill</small></button><button class="move-btn" data-action="burst">⚡ Wild Burst <small>POWERFUL · may miss</small></button><button class="catch-btn" data-action="catch">◉ Toss a capture pod <small>${Math.round(catchChance()*100)}% chance</small></button>`;acts.querySelectorAll('button').forEach(b=>b.onclick=()=>battleAction(b.dataset.action));}
function catchChance(){return Math.min(.9,.25+.58*(1-battle.hp/battle.maxHp))}
function say(msg){$('#battleLog').textContent=msg}
function awardXP(amount){let m=aliveParty()||state.party[0];m.xp=(m.xp||0)+amount;state.xp+=amount;if(state.xp>=100){state.xp-=100;state.rank++;toast(`Ranger rank up! You're rank ${state.rank}.`)}while(m.xp>=m.level*12){m.xp-=m.level*12;m.level++;m.maxHp+=5;m.hp=Math.min(m.maxHp,m.hp+8);m.atk++;let evo=evolve[m.id];if(evo&&m.level>=evo.level){let old=species[m.id],next=species[evo.to];m.id=evo.to;m.maxHp+=12;m.hp=m.maxHp;addSeen(m.id);setTimeout(()=>toast(`${old.name} evolved into ${next.name}!`),450)}}persist()}
