function battleAction(action){if(!battle||turnBusy)return;turnBusy=true;let ally=aliveParty();if(!ally){turnBusy=false;enemyTurn();return}let wild=species[battle.id],dmg=0;
 if(action==='catch'){if(Math.random()<catchChance()){let m=makeMon(battle.id,Math.max(2,ally.level-1));m.hp=Math.ceil(m.maxHp*(.6+Math.random()*.4));addSeen(m.id);if(state.party.length<6){state.party.push(m);say(`${wild.name} was captured and joined your party!`)}else{state.box.push(m);say(`${wild.name} was captured and sent to your sanctuary!`)}awardXP(8);setTimeout(()=>endBattle(`${wild.name} added to your collection!`),850);return}else{say(`The capture pod shook loose! ${wild.name} broke free.`);setTimeout(()=>{if(battle){enemyTurn();turnBusy=false}},500);return}}
 if(action==='ability'){let typ=species[ally.id].type;dmg=Math.floor(ally.atk*(1.15+Math.random()*.4));if(['Bloom','Grove','Tide'].includes(typ)){let heal=Math.ceil(ally.maxHp*.14);ally.hp=Math.min(ally.maxHp,ally.hp+heal);say(`${species[ally.id].ability}! ${monName(ally)} dealt ${dmg} damage and recovered ${heal} HP.`)}else if(['Flame','Spark','Frost'].includes(typ)){dmg+=Math.ceil(ally.atk*.55);say(`${species[ally.id].ability}! A charged strike deals ${dmg} damage.`)}else{ally.hp=Math.min(ally.maxHp,ally.hp+Math.ceil(ally.maxHp*.08));say(`${species[ally.id].ability}! A sharp strike for ${dmg} damage.`)}}
 else if(action==='burst'){if(Math.random()<.22){say(`${monName(ally)}'s Wild Burst missed!`);setTimeout(()=>{if(battle){enemyTurn();turnBusy=false}},450);return}dmg=Math.floor(ally.atk*(1.8+Math.random()*.65));say(`Wild Burst! ${monName(ally)} hits for ${dmg} damage!`)}else{dmg=Math.floor(ally.atk*(.8+Math.random()*.55));say(`${monName(ally)} used Trail Swipe for ${dmg} damage!`)}
 battle.hp=Math.max(0,battle.hp-dmg);if(battle.hp===0){say(`The wild ${wild.name} calmed down. Your companion gained experience!`);awardXP(12);state.coins+=5;setTimeout(()=>endBattle(`Victory! +12 XP · +5 ✦`),800);return}persist();renderBattle();setTimeout(()=>{if(battle){enemyTurn();turnBusy=false;renderBattle()}},650)}
